function BrandMark(){return <img className="brand-icon" src="/team.png" alt="TeamForgeAI"/>}

function RequireAuth() { const { user, loading } = useAuth(); const location = useLocation(); if (loading) return <div className="screen-center"><div className="spinner" /></div>; if (user) return <WorkspaceProvider><Outlet /></WorkspaceProvider>; if (location.pathname === '/join') return <Navigate to="/login" state={{ from: location }} replace />; return <LandingPage/>; }

function AuthPage({ mode }) {
  const { login, register, verifyRegistration, resendRegistrationOtp, user } = useAuth(); const navigate = useNavigate(); const location = useLocation();
  const [name, setName] = useState(''), [email, setEmail] = useState(''), [password, setPassword] = useState(''), [code, setCode] = useState(''), [otpSent, setOtpSent] = useState(false), [show, setShow] = useState(false), [busy, setBusy] = useState(false);
  if (user) return <Navigate to="/" replace />;
  async function submit(event) { event.preventDefault(); setBusy(true); try { if(mode==='register'&&!otpSent){await register(name,email,password);setOtpSent(true);toast.success(`Verification code sent to ${email}`);return;} if(mode==='register')await verifyRegistration(email,code);else await login(email,password); navigate(location.state?.from ? `${location.state.from.pathname}${location.state.from.search||''}` : '/', {replace:true}); } catch (e) { toast.error(e.message); } finally { setBusy(false); } }
  async function resendCode(){setBusy(true);try{await resendRegistrationOtp(email);toast.success(`A new code was sent to ${email}`);}catch(e){toast.error(e.message);}finally{setBusy(false);}}
  return <><LandingPage/>{user ? null : <main className="auth-screen auth-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)navigate('/',{replace:true});}}><section className="auth-story"><Link to="/" className="brand"><BrandMark/> TeamForge<span className="brand-ai">AI</span></Link><div className="story-copy"><div className="eyebrow"><Sparkles size={14}/> COLLABORATION, WITH MOMENTUM</div><h1>Think together.<br/><span>Build together.</span></h1><p>Give your team one calm place to turn ideas into work that ships.</p><div className="feature-list"><div><Check/> Keep projects and conversations connected</div><div><Check/> Turn a shared plan into clear next steps</div><div><Check/> See who's doing what, without the noise</div></div></div><div className="story-foot">A workspace for work worth doing.</div></section><section className="auth-form-wrap"><button className="icon-button auth-close" aria-label="Close" onClick={()=>navigate('/',{replace:true})}><X size={18}/></button><form className="auth-form" onSubmit={submit}><div className="eyebrow">TEAM WORKSPACE</div><h2>{mode === 'register' ? otpSent ? 'Verify your email' : 'Create your account' : 'Welcome back'}</h2><p className="muted">{mode === 'register' ? otpSent ? `We sent a 4-digit code to ${email}. Enter it below to create your account.` : 'Start your team workspace in a few seconds.' : 'Sign in to pick up where your team left off.'}</p>
    {mode === 'register' && !otpSent && <label>Full name<input autoComplete="name" required minLength={2} maxLength={80} value={name} onChange={e => setName(e.target.value)} placeholder="Alex Morgan"/> </label>}
    <label>Email<input autoComplete="email" type="email" required maxLength={254} value={email} onChange={e => setEmail(e.target.value)} placeholder="you@company.com" readOnly={otpSent}/></label>
    {mode === 'register' && otpSent ? <><p className="muted">Enter the 4-digit code we sent to your Gmail inbox. The code expires in 10 minutes.</p><label>Verification code<input autoFocus autoComplete="one-time-code" inputMode="numeric" type="text" pattern="[0-9]{4}" maxLength={4} required value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,4))} placeholder="0000"/></label><div className="otp-actions"><button type="button" className="text-button" disabled={busy} onClick={resendCode}>Resend code</button><button type="button" className="text-button" disabled={busy} onClick={()=>{setOtpSent(false);setCode('');}}>Edit registration details</button></div></> : <label>Password<div className="password-wrap"><input autoComplete={mode === 'register' ? 'new-password' : 'current-password'} type={show ? 'text' : 'password'} required minLength={mode === 'register' ? 10 : 1} maxLength={72} value={password} onChange={e => setPassword(e.target.value)} placeholder={mode === 'register' ? 'At least 10 characters' : 'Your password'}/><button className="text-button" type="button" onClick={() => setShow(v => !v)}>{show ? 'Hide' : 'Show'}</button></div></label>}
    <button className="button primary full" disabled={busy}>{busy ? 'Please wait…' : mode === 'register' ? otpSent ? 'Verify and create account' : 'Send verification code' : 'Sign in'} <ArrowRight size={16}/></button><p className="auth-switch">{mode === 'register' ? 'Already have an account?' : 'New to TeamForge?'} <Link to={mode === 'register' ? '/login' : '/register'} state={location.state}>{mode === 'register' ? 'Sign in' : 'Create an account'}</Link></p>
  </form></section></main>}</>;
}

function LandingPage(){const stepsRef=useRef(null);useEffect(()=>{const node=stepsRef.current;if(!node)return;const reveal=()=>{const box=node.getBoundingClientRect();const inView=box.top<window.innerHeight*.8&&box.bottom>window.innerHeight*.2;node.classList.toggle("steps-visible",inView);};window.addEventListener("scroll",reveal,{passive:true});window.addEventListener("resize",reveal);reveal();return()=>{window.removeEventListener("scroll",reveal);window.removeEventListener("resize",reveal);};},[]);return <div className="landing-page"><header className="landing-nav"><Link to="/" className="brand"><BrandMark/> TeamForge<span className="brand-ai">AI</span></Link><nav><a href="#features">Features</a><a href="#how-it-works">How it works</a><a href="#faq">FAQ</a></nav><Link className="button primary landing-login" to="/login">Log in <ArrowRight size={15}/></Link></header><main><section className="landing-hero" id="home"><div className="hero-orbit orbit-one"/><div className="hero-orbit orbit-two"/><div className="hero-copy"><div className="hero-kicker"><Sparkles size={14}/> YOUR TEAM’S NEXT BIG THING STARTS HERE</div><h1>Great work<br/>happens <span>together.</span></h1><p>TeamForgeAI brings projects, tasks, conversations, and smart planning into one shared workspace—so your team can spend less time coordinating and more time creating.</p><a className="button primary hero-cta" href="#features">Explore the workspace <ArrowRight size={16}/></a><div className="hero-proof"><span className="proof-avatars"><i>A</i><i>M</i><i>J</i></span><span>One workspace. Every moving part.</span></div></div><div className="hero-visual"><div className="visual-glow"/><div className="preview-window"><div className="preview-top"><span className="preview-dots">● ● ●</span><span>Team workspace</span><span className="preview-live"><i/> LIVE</span></div><div className="preview-body"><div className="preview-sidebar"><b><Layers3 size={16}/> TeamForge</b><span className="active">▦ &nbsp; Overview</span><span>▤ &nbsp; Projects</span><span>✓ &nbsp; My tasks</span><span>✦ &nbsp; AI planner</span></div><div className="preview-content"><small>MONDAY, OCTOBER 28</small><h3>Good morning, team ✨</h3><p>Here’s what’s moving today.</p><div className="preview-stats"><div><small>ACTIVE PROJECTS</small><b>06</b></div><div><small>OPEN TASKS</small><b>24</b></div></div><div className="preview-task"><i className="task-check">✓</i><span><b>Launch campaign</b><small>Design · Due today</small></span><em>In progress</em></div><div className="preview-task"><i className="task-check purple">✦</i><span><b>Plan next sprint</b><small>Product · Tomorrow</small></span><em className="done">On track</em></div></div></div></div><div className="float-note"><WandSparkles size={16}/><span><b>AI project planner</b><small>From idea to action plan</small></span></div></div><div className="hero-scroll">SCROLL TO DISCOVER <span>↓</span></div></section><section className="landing-about" id="features"><div className="about-heading"><div className="hero-kicker"><span className="kicker-line"/> BUILT FOR THE WAY TEAMS WORK</div><h2>Everything in sync.<br/><span>Everyone moving.</span></h2><p>From the first brainstorm to the final checkmark, TeamForgeAI gives your team the clarity and momentum to make good ideas happen.</p></div><div className="feature-cards" ref={stepsRef}><article><span className="feature-icon blue"><Layers3/></span><small>01 / PLAN</small><h3>Projects with purpose</h3><p>Keep goals, milestones, and the people behind them in one clear view.</p></article><article><span className="feature-icon violet"><Check/></span><small>02 / MAKE PROGRESS</small><h3>Tasks that move</h3><p>Turn big goals into focused next steps and see progress as it happens.</p></article><article><span className="feature-icon mint"><WandSparkles/></span><small>03 / THINK BIGGER</small><h3>AI, on your side</h3><p>Use the AI planner to shape ideas into practical plans your team can start today.</p></article></div><div className="about-ribbon"><Sparkles size={15}/> LESS STATUS CHASING. MORE MOMENTUM.</div></section><section className="landing-steps" id="how-it-works"><div className="about-heading"><div className="hero-kicker"><span className="kicker-line"/> A CLEARER WAY TO COLLABORATE</div><h2>From idea to<br/><span>Done.</span></h2><p>Get your team aligned, organize the work, and keep every project moving forward.</p></div><div className="step-list"><article><span>01</span><div><h3>Bring your team together</h3><p>Create a workspace and invite the people you work with.</p></div></article><article><span>02</span><div><h3>Shape the work</h3><p>Organize projects, tasks, notes, and conversations in one place.</p></div></article><article><span>03</span><div><h3>Make progress visible</h3><p>Track what is moving and use the AI planner to find next steps.</p></div></article></div></section><section className="landing-faq" id="faq"><div className="about-heading"><div className="hero-kicker"><span className="kicker-line"/> GOOD QUESTIONS</div><h2>Quick answers.<br/><span>Clear head.</span></h2></div><div className="faq-list"><details><summary>What is TeamForgeAI?</summary><p>A shared workspace for teams to manage projects, tasks, notes, and conversations, with an AI planner to help turn ideas into actionable plans.</p></details><details><summary>Who is it for?</summary><p>Teams and collaborators who want one organized place to plan work, share updates, and follow progress.</p></details><details><summary>How does the AI planner help?</summary><p>Describe a goal or idea and the planner can help break it into phases and practical next steps.</p></details></div></section></main><footer className="landing-footer"><div className="footer-top"><div className="footer-author"><p className="footer-credit"><span>Created by</span><b>Ansh Rokde</b></p></div><div className="footer-social"><a href="https://github.com/rokdeansh" target="_blank" rel="noreferrer" aria-label="GitHub"><Github/></a><a href="https://www.linkedin.com/in/ansh-rokde-394630338/" target="_blank" rel="noreferrer" aria-label="LinkedIn"><Linkedin/></a></div></div><div className="footer-wordmark">TEAMFORGE<span>AI</span></div><div className="footer-bottom"><span>© {new Date().getFullYear()} TeamForgeAI. All rights reserved.</span><span>Made for teams that make things happen.</span></div></footer></div>}

function Shell() {
  const { user, logout, updateProfile } = useAuth(); const { items, selected, setSelectedId, refresh } = useWorkspace(); const location = useLocation(); const [mobileOpen, setMobileOpen] = useState(false), [createOpen, setCreateOpen] = useState(false), [workspaceName, setWorkspaceName] = useState(''), [searchOpen, setSearchOpen] = useState(false), [deleteWorkspaceTarget, setDeleteWorkspaceTarget] = useState(null);
  const navigate = useNavigate(); const queryClient = useQueryClient(); const projectMatch = useMatch('/projects/:projectId'); const projectId = projectMatch?.params.projectId; const { data: breadcrumbData } = useQuery({ queryKey: ['project', projectId], queryFn: () => api.get(`/projects/${projectId}`), enabled: !!projectId });
  async function createWorkspace(e) { e.preventDefault(); try { const data = await api.post('/workspaces', { name: workspaceName }); await refresh(); setSelectedId(data.workspace._id); setWorkspaceName(''); setCreateOpen(false); toast.success('Workspace created'); } catch (err) { toast.error(err.message); } }
  async function deleteWorkspace() { if (!deleteWorkspaceTarget) return; try { await api.delete(`/workspaces/${deleteWorkspaceTarget._id}`); await queryClient.invalidateQueries({ queryKey: ['workspaces'] }); queryClient.removeQueries({ queryKey: ['dashboard'] }); setDeleteWorkspaceTarget(null); navigate('/', { replace: true }); toast.success('Workspace deleted'); } catch (err) { toast.error(err.message); } }
  useEffect(() => { function key(e) { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setSearchOpen(v => !v); } if (e.key === 'Escape') { setSearchOpen(false); setCreateOpen(false); } } window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, []);
  const nav = [['Overview', '/', LayoutDashboard], ['Projects', '/projects', FolderKanban], ['My tasks', '/my-tasks', ListTodo], ['Notes', '/notes', StickyNote], ['Chat', '/chat', MessageSquare], ['Members', '/members', Users], ['AI planner', '/ai', Sparkles], ['Settings', '/settings', Settings]];
  return <div className="app-shell"><aside className={`sidebar ${mobileOpen ? 'open' : ''}`}><Link to="/" className="brand"><BrandMark/> TeamForge<span className="brand-ai">AI</span></Link><DropdownMenu.Root><DropdownMenu.Trigger className="workspace-trigger"><span className="workspace-avatar">{selected?.name?.[0]?.toUpperCase()||'W'}</span><span className="workspace-trigger-copy"><b>{selected?.name||'Select workspace'}</b><small>{selected?.role||''}</small></span><ChevronDown size={14}/></DropdownMenu.Trigger><DropdownMenu.Portal><DropdownMenu.Content className="menu-content workspace-menu" sideOffset={7} align="start">{items.map(w=><div className="workspace-row" key={w._id}><DropdownMenu.Item className="menu-item workspace-select-item" onSelect={()=>setSelectedId(w._id)}><span className="workspace-menu-avatar">{w.name?.[0]?.toUpperCase()||'W'}</span><span className="menu-grow">{w.name}<small>{w.role}</small></span>{w._id===selected?._id&&<Check size={15}/>}</DropdownMenu.Item>{w.role==='owner'&&<DropdownMenu.Root><DropdownMenu.Trigger className="workspace-more" aria-label={`Options for ${w.name}`}><MoreVertical size={17}/></DropdownMenu.Trigger><DropdownMenu.Portal><DropdownMenu.Content className="menu-content" side="right" align="start" sideOffset={5}><DropdownMenu.Item className="menu-item menu-danger" onSelect={()=>setDeleteWorkspaceTarget(w)}><Trash2 size={15}/> Delete workspace</DropdownMenu.Item></DropdownMenu.Content></DropdownMenu.Portal></DropdownMenu.Root>}</div>)}<DropdownMenu.Separator className="menu-separator"/><DropdownMenu.Item className="menu-item menu-create" onSelect={()=>setCreateOpen(true)}><Plus size={15}/> Create workspace</DropdownMenu.Item></DropdownMenu.Content></DropdownMenu.Portal></DropdownMenu.Root><nav className="side-nav">{nav.map(([label, path, Icon]) => <NavLink key={path} to={path} end={path === '/'} onClick={() => setMobileOpen(false)} className={({isActive}) => `nav-link ${isActive ? 'active' : ''}`}><Icon size={18}/><span>{label}</span></NavLink>)}</nav><div className="sidebar-recent"><span className="eyebrow">RECENT PROJECTS</span><RecentProjects/></div><div className="sidebar-bottom"><DropdownMenu.Root><DropdownMenu.Trigger className="user-menu-trigger"><span className="user-avatar">{user?.name?.[0]?.toUpperCase()}</span><span className="user-info"><b>{user?.name}</b><small>{user?.email}</small></span><MoreHorizontal size={17}/></DropdownMenu.Trigger><DropdownMenu.Portal><DropdownMenu.Content className="menu-content user-menu" side="top" align="end" sideOffset={8}><DropdownMenu.Item className="menu-item" onSelect={()=>navigate('/settings')}>Profile</DropdownMenu.Item><DropdownMenu.Sub><DropdownMenu.SubTrigger className="menu-item">Theme <ChevronDown size={14}/></DropdownMenu.SubTrigger><DropdownMenu.Portal><DropdownMenu.SubContent className="menu-content" sideOffset={5}><DropdownMenu.RadioGroup value={user?.themePreference||'system'} onValueChange={async theme=>{try{await updateProfile({themePreference:theme});}catch(err){toast.error(err.message);}}}><DropdownMenu.RadioItem className="menu-item" value="light"><Sun size={15}/> Light</DropdownMenu.RadioItem><DropdownMenu.RadioItem className="menu-item" value="dark"><Moon size={15}/> Dark</DropdownMenu.RadioItem><DropdownMenu.RadioItem className="menu-item" value="system"><Monitor size={15}/> System</DropdownMenu.RadioItem></DropdownMenu.RadioGroup></DropdownMenu.SubContent></DropdownMenu.Portal></DropdownMenu.Sub><DropdownMenu.Separator className="menu-separator"/><DropdownMenu.Item className="menu-item menu-danger" onSelect={async()=>{await logout();queryClient.clear();navigate('/login');}}><LogOut size={15}/> Sign out</DropdownMenu.Item></DropdownMenu.Content></DropdownMenu.Portal></DropdownMenu.Root></div></aside>
    <div className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileOpen(v => !v)} aria-label="Open navigation"><Menu size={20}/></button><div className="breadcrumb"><Link to="/projects" className="breadcrumb-workspace">{selected?.name||'Team workspace'}</Link><span className="crumb-sep">/</span><strong>{projectMatch?breadcrumbData?.project?.name||'Project':nav.find(n=>n[1]===location.pathname)?.[0]||'Project'}</strong></div><div className="topbar-actions"><button className="search-trigger" onClick={() => setSearchOpen(true)}><Search size={15}/><span>Search anything</span><kbd>⌘ K</kbd></button><NotificationButton/><Link className="button ai-button" to="/ai" title="Ask AI" aria-label="Ask AI"><Sparkles size={17}/><span>Ask AI</span></Link></div></header><main className="page-container"><Suspense fallback={<PageLoading/>}><Outlet/></Suspense></main></div>
    {mobileOpen && <button className="mobile-scrim" onClick={() => setMobileOpen(false)} aria-label="Close navigation"/>}
    {deleteWorkspaceTarget && <Modal title="Delete workspace?" close={() => setDeleteWorkspaceTarget(null)}><p>This permanently deletes <strong>{deleteWorkspaceTarget.name}</strong>, including its projects, tasks, notes, messages, and members.</p><div className="modal-actions"><button className="button ghost" onClick={() => setDeleteWorkspaceTarget(null)}>Cancel</button><button className="button danger" onClick={deleteWorkspace}><Trash2 size={15}/> Delete workspace</button></div></Modal>}
    {createOpen && <Modal title="Create a workspace" close={() => setCreateOpen(false)}><form onSubmit={createWorkspace}><label>Workspace name<input autoFocus required minLength={2} maxLength={100} value={workspaceName} onChange={e => setWorkspaceName(e.target.value)} placeholder="Product team"/></label><div className="modal-actions"><button type="button" className="button ghost" onClick={() => setCreateOpen(false)}>Cancel</button><button className="button primary">Create workspace</button></div></form></Modal>}
    {searchOpen && <Modal title="Search TeamForge" close={() => setSearchOpen(false)}><GlobalSearch close={() => setSearchOpen(false)}/></Modal>}
  </div>;
}
function RecentProjects(){ const { selectedId }=useWorkspace(); const {data}=useQuery({queryKey:['projects', selectedId],queryFn:()=>api.get('/projects',{params:{workspaceId:selectedId,limit:4}}),enabled:!!selectedId}); return <div className="recent-list">{(data?.items||[]).slice(0,4).map(p=><Link key={p._id} to={`/projects/${p._id}`}><span className="recent-dot"/>{p.name}</Link>)}{!data?.items?.length&&<small className="muted">Your projects will appear here</small>}</div>; }
function GlobalSearch({ close }) { const { selectedId }=useWorkspace(); const [term,setTerm]=useState(''); const {data}=useQuery({queryKey:['search',selectedId,term],queryFn:async()=>{const [p,t,n]=await Promise.all([api.get('/projects',{params:{workspaceId:selectedId,search:term,limit:5}}),api.get('/tasks',{params:{workspaceId:selectedId,search:term,limit:5}}),api.get('/notes',{params:{workspaceId:selectedId,search:term,limit:5}})]);return {projects:p.items,tasks:t.items,notes:n.items};},enabled:term.trim().length>1}); return <><div className="search-input"><Search size={17}/><input autoFocus placeholder="Search projects, tasks, notes…" value={term} onChange={e=>setTerm(e.target.value)}/></div><div className="search-quick-actions"><strong>Quick actions</strong><Link onClick={close} to="/projects?create=1"><Plus size={14}/> New project</Link><Link onClick={close} to="/my-tasks?create=1"><Plus size={14}/> New task</Link>{[["Overview","/"],["Projects","/projects"],["My tasks","/my-tasks"],["Notes","/notes"],["Chat","/chat"],["Members","/members"],["AI planner","/ai"]].map(([label,path])=><Link onClick={close} key={path} to={path}>{label}</Link>)}</div><div className="search-results">{term.length<2?<p className="muted">Type at least two characters to search this workspace.</p>:<>{[['Projects',data?.projects||[],'/projects/'],['Tasks',data?.tasks||[],'/projects/'],['Notes',data?.notes||[],'/notes']].map(([label,items,path])=><section key={label}><small className="eyebrow">{label}</small>{items.map(item=><Link onClick={close} key={item._id} to={label==='Projects'?`/projects/${item._id}`:label==='Tasks'?`/projects/${typeof item.project==='object'?item.project?._id:item.project}`:'/notes'}>{item.name||item.title}</Link>)}</section>)}</>}</div></>; }
function NotificationButton(){const [open,setOpen]=useState(false),qc=useQueryClient();const {data}=useQuery({queryKey:['notifications'],queryFn:()=>api.get('/notifications',{params:{limit:8}}),enabled:open,refetchInterval:open?30000:false});async function read(id){try{await api.patch(`/notifications/${id}/read`,{});await qc.invalidateQueries({queryKey:['notifications']});}catch(e){toast.error(e.message);}}async function readAll(){try{await api.post('/notifications/read-all',{});await qc.invalidateQueries({queryKey:['notifications']});}catch(e){toast.error(e.message);}}return <Popover.Root open={open} onOpenChange={setOpen}><Popover.Trigger asChild><button className="icon-button notification-button" aria-label="Notifications"><Bell size={17}/>{data?.unreadCount>0&&<i>{data.unreadCount>9?'9+':data.unreadCount}</i>}</button></Popover.Trigger><Popover.Portal><Popover.Content className="notification-popover" align="end" sideOffset={8} collisionPadding={16}><div className="notification-head"><b>Notifications</b>{data?.unreadCount>0&&<button onClick={readAll}>Mark all read</button>}</div><div className="notification-list">{data?.items?.length?data.items.map(n=><button className={`notification-row ${n.read?'read':''}`} key={n._id} onClick={()=>read(n._id)}><span className="notification-dot"/><span>{notificationText(n)}<small>{format(new Date(n.createdAt),'MMM d, h:mm a')}</small></span></button>):<p className="muted notification-empty"><Bell size={18}/>You’re all caught up</p>}</div></Popover.Content></Popover.Portal></Popover.Root>;}
function notificationText(n){const actor=n.actor?.name||'A teammate';if(n.type==='task_assigned')return `${actor} assigned you a task`;if(n.type==='task_status_changed')return `${actor} changed a task status`;if(n.type==='project_updated')return `${actor} updated a project`;return `${actor} added you to a workspace`;}
function Modal({title,close,children}) { const dialogRef=useRef(null),closeRef=useRef(close);closeRef.current=close;useEffect(()=>{const dialog=dialogRef.current;if(!dialog)return;const previous=document.activeElement;const focusable=()=>[...dialog.querySelectorAll('button:not(:disabled),[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex]:not([tabindex="-1"])')];(dialog.querySelector('[autofocus]')||focusable()[0]||dialog).focus();function keydown(event){if(event.key==='Escape'){event.preventDefault();closeRef.current();return;}if(event.key==='Tab'){const nodes=focusable();if(!nodes.length){event.preventDefault();dialog.focus();return;}if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes[nodes.length-1].focus();}else if(!event.shiftKey&&document.activeElement===nodes[nodes.length-1]){event.preventDefault();nodes[0].focus();}}}dialog.addEventListener('keydown',keydown);return()=>{dialog.removeEventListener('keydown',keydown);previous?.focus?.();};},[]);return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><section ref={dialogRef} tabIndex={-1} className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={close} aria-label="Close dialog"><X size={18}/></button></div>{children}</section></div>; }
function PageHeader({eyebrow,title,description,action}) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description&&<p>{description}</p>}</div>{action}</div>; }
function PageLoading({kind='page'}){const count={overview:5,projects:6,board:4,tasks:4,notes:3,members:5}[kind]||3;return <div className={`loading-stack loading-${kind}`} aria-label="Loading content"><div className="skeleton title-skeleton"/><div className="skeleton-grid">{Array.from({length:count},(_,index)=><div className="skeleton card-skeleton" key={index}/>)}</div></div>;}
function Empty({icon:Icon=Activity,title,body,action}) { return <div className="empty-state"><span className="empty-icon"><Icon size={22}/></span><h3>{title}</h3><p>{body}</p>{action}</div>; }
function ErrorState({error,retry}) { return <div className="error-state"><strong>We couldn’t load this data</strong><p>{error?.message||'Check your connection and try again.'}</p><button className="button secondary" onClick={retry}>Try again</button></div>; }

function Dashboard(){
 const {user}=useAuth(),{selectedId}=useWorkspace(); const {data,isLoading,error,refetch}=useQuery({queryKey:['dashboard',selectedId],queryFn:()=>api.get('/dashboard',{params:{workspaceId:selectedId}}),enabled:!!selectedId});
 if(!selectedId)return <Empty icon={Users} title="Create your first workspace" body="Workspaces bring projects, notes, and teammates together." action={<Link className="button primary" to="/projects">Get started <ArrowRight size={15}/></Link>}/>;
 if(isLoading)return <PageLoading kind="overview"/>; if(error)return <ErrorState error={error} retry={refetch}/>;
 const taskCounts=Object.fromEntries((data.taskStatus||[]).map(x=>[x._id,x.count])),projectCounts=Object.fromEntries((data.projectStatus||[]).map(x=>[x._id,x.count]));
 return <><PageHeader eyebrow="YOUR WORKSPACE" title={`Good ${getGreeting()}, ${user?.name?.split(' ')[0] || 'there'}`} description="Here’s what’s moving across your team." action={<Link className="button primary" to="/projects"><Plus size={16}/> New project</Link>}/><div className="stat-grid"><Stat label="Due this week" value={data.dueSoon?.length||0}/><Stat label="Active projects" value={projectCounts['In Progress']||0}/><Stat label="Open tasks" value={STATUS.slice(0,3).reduce((n,s)=>n+(taskCounts[s]||0),0)}/><Stat label="Completed" value={taskCounts.Completed||0}/><Stat label="Overdue" value={data.overdueCount||0}/></div><div className="dashboard-grid"><DashboardCharts data={data}/><section className="panel"><div className="panel-heading"><div><h2>Due this week</h2><p>Tasks assigned to you</p></div><Link to="/my-tasks" className="subtle-link">View all <ArrowRight size={14}/></Link></div>{data.dueSoon?.length?<div className="compact-list">{data.dueSoon.map(task=><Link key={task._id} className="compact-row" to={`/projects/${task.project}`}><span className={`task-mark ${slug(task.status)}`}/><span className="grow">{task.title}<small>{format(new Date(task.dueDate),'MMM d')} · {task.status}</small></span></Link>)}</div>:<div className="mini-empty">Nothing due in the next seven days.</div>}</section><section className="panel"><div className="panel-heading"><div><h2>Recent activity</h2><p>Recent changes in this workspace</p></div></div>{data.recentActivity?.length?<div className="compact-list">{data.recentActivity.map(item=><div className="compact-row" key={item._id}><span className="activity-mark"><Activity size={13}/></span><span className="grow">{item.actor?.name||'A teammate'} {activityLabel(item)}<small>{format(new Date(item.createdAt),'MMM d, h:mm a')}</small></span></div>)}</div>:<div className="mini-empty">Activity will appear as your team works.</div>}</section><section className="panel wide-panel"><div className="panel-heading"><div><h2>Recently updated projects</h2><p>Pick up where your team left off</p></div><Link to="/projects" className="subtle-link">All projects <ArrowRight size={14}/></Link></div>{data.recentProjects?.length?<div className="project-table">{data.recentProjects.map(p=><Link key={p._id} className="project-line" to={`/projects/${p._id}`}><span className="project-symbol"><FolderKanban size={17}/></span><span className="grow">{p.name}<small>{p.deadline?`Due ${format(new Date(p.deadline),'MMM d')}`:'No deadline'}</small></span><Badge value={p.status}/><span className="muted tiny">Updated {format(new Date(p.updatedAt),'MMM d')}</span></Link>)}</div>:<Empty icon={FolderKanban} title="No projects yet" body="Create a project to start planning the work." action={<Link className="button primary" to="/projects">Create a project</Link>}/>}</section></div></>;
}
function getGreeting(){const h=new Date().getHours();return h<12?'morning':h<18?'afternoon':'evening';}
function activityLabel(item){if(item.type==='task_assigned')return `assigned ${item.details?.title||'a task'}`;if(item.type==='task_status_changed')return `moved ${item.details?.title||'a task'} to ${item.details?.to||'a new status'}`;if(item.type==='project_updated')return 'updated a project';return 'joined a workspace';}
function Stat({label,value,subtitle}){return <div className="stat-card"><span>{label}</span><strong>{value??'—'}</strong>{subtitle&&<small>{subtitle}</small>}</div>;}
function Badge({value}) { return <span className={`badge ${slug(value)}`}><i aria-hidden="true"/>{value}</span>; }
function slug(value=''){return value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');}

function Projects(){ const {selectedId,selected}=useWorkspace(),qc=useQueryClient(),location=useLocation();const [search,setSearch]=useState(''),[modal,setModal]=useState(false),[name,setName]=useState(''),[description,setDescription]=useState('');
 useEffect(()=>{if(new URLSearchParams(location.search).get('create')==='1')setModal(true);},[location.search]);
 const membersQuery=useQuery({queryKey:['members',selectedId],queryFn:()=>api.get(`/workspaces/${selectedId}/members`),enabled:!!selectedId});
 const {data,isLoading,error,refetch}=useQuery({queryKey:['projects',selectedId],queryFn:()=>api.get('/projects',{params:{workspaceId:selectedId,search,limit:50}}),enabled:!!selectedId});
 async function create(e){e.preventDefault();try{await api.post('/projects',{workspaceId:selectedId,name,description});await qc.invalidateQueries({queryKey:['projects',selectedId]});setName('');setDescription('');setModal(false);toast.success('Project created');}catch(err){toast.error(err.message);}}
 return <><PageHeader eyebrow="WORKSPACE" title="Projects" description="Keep goals, tasks, and people connected." action={selected&&["owner","admin"].includes(selected.role)&&<button className="button primary" onClick={()=>setModal(true)}><Plus size={16}/> New project</button>}/><div className="toolbar"><div className="inline-search"><Search size={16}/><input aria-label="Search projects" placeholder="Search projects" value={search} onChange={e=>setSearch(e.target.value)}/></div><span className="muted tiny">{pluralize(data?.total||0,'project')}</span></div>{isLoading?<PageLoading kind="projects"/>:error?<ErrorState error={error} retry={refetch}/>:data?.items?.length?<div className="project-grid">{data.items.map(p=><ProjectCard key={p._id} project={p} workspaceMembers={membersQuery.data?.items||[]}/>)}</div>:<Empty icon={FolderKanban} title="No projects found" body={search?'Try a different search term.':'Create a project for your team’s next goal.'} action={!search&&selected&&["owner","admin"].includes(selected.role)&&<button className="button primary" onClick={()=>setModal(true)}><Plus size={16}/> Create project</button>}/>}{modal&&<Modal title="Create project" close={()=>setModal(false)}><form onSubmit={create}><label>Project name<input autoFocus required minLength={2} maxLength={140} value={name} onChange={e=>setName(e.target.value)} placeholder="Website refresh"/></label><label>Description<textarea rows="3" maxLength={4000} value={description} onChange={e=>setDescription(e.target.value)} placeholder="What outcome are you working toward?"/></label><div className="modal-actions"><button type="button" className="button ghost" onClick={()=>setModal(false)}>Cancel</button><button className="button primary">Create project</button></div></form></Modal>}</>;
}
function ProjectCard({project:p,workspaceMembers=[]}){const done=p.completedTasks||0,total=p.taskTotal||0,progress=total?Math.round(done/total*100):0,memberIds=(p.members||[]).map(member=>String(member?._id||member)),projectMembers=workspaceMembers.filter(member=>memberIds.includes(String(member.user?._id))).map(member=>member.user);return <Link className={`project-card ${p.status==='Completed'?'completed-project':undefined}`} to={`/projects/${p._id}`}><div className="project-card-top"><span className="project-symbol"><FolderKanban size={18}/></span><span className="project-card-people"><AvatarStack users={projectMembers}/><span className="muted tiny">{pluralize(p.members?.length||0,'member')}</span></span></div><h3>{p.name}</h3><p>{p.description||"No description added yet."}</p><div className="project-card-meta"><Badge value={p.status}/>{p.deadline&&<span className={`deadline ${isPast(new Date(p.deadline))&&p.status!=="Completed"?"overdue":""}`}><CalendarDays size={13}/>{format(new Date(p.deadline),'MMM d')}</span>}</div><div className="progress-label"><span>Progress</span><span>{progress}% · {done} of {pluralize(total,'task')}</span></div><div className="progress-track"><i style={{width:`${progress}%`}}/></div></Link>;}

function ProjectDetail(){const {projectId}=useParams(),{selectedId,selected}=useWorkspace(),{user}=useAuth(),qc=useQueryClient();const [tab,setTab]=useState('Board'),[mobileStatus,setMobileStatus]=useState(STATUS[0]),[newTitle,setNewTitle]=useState({}),[editingTask,setEditingTask]=useState(null);const {data,isLoading,error,refetch}=useQuery({queryKey:['project',projectId],queryFn:()=>api.get(`/projects/${projectId}`)});const {data:taskData,isLoading:tasksLoading,error:tasksError,refetch:refetchTasks}=useQuery({queryKey:['project-tasks',projectId],queryFn:()=>api.get('/tasks',{params:{workspaceId:selectedId,projectId,limit:100}})});const project=data?.project,tasks=taskData?.items||[];
 async function createTask(e,status='To Do'){e.preventDefault();const title=(newTitle[status]||'').trim();if(!title)return;try{await api.post('/tasks',{workspaceId:selectedId,projectId,title,status,assignees:user?.id?[user.id]:[]});setNewTitle(current=>({...current,[status]:''}));await Promise.all([qc.invalidateQueries({queryKey:['project-tasks',projectId]}),qc.invalidateQueries({queryKey:['my-tasks']})]);toast.success('Task added');}catch(err){toast.error(err.message);}}
 async function moveTask(id,targetId){try{const overTask=tasks.find(task=>task._id===targetId);const status=STATUS.includes(targetId)?targetId:overTask?.status;if(!status)return;const order=Math.max(-1,...tasks.filter(task=>task.status===status&&task._id!==id).map(task=>task.order||0))+1;await api.patch(`/tasks/${id}`,{status,order});await qc.invalidateQueries({queryKey:['project-tasks',projectId]});}catch(e){toast.error(e.message);}}
 if(isLoading)return <PageLoading/>;if(error)return <ErrorState error={error} retry={refetch}/>;
 return <><div className="project-detail-head"><div><div className="eyebrow"><Link to="/projects">PROJECTS</Link> / {project?.name||'Project'}</div><h1>{project?.name}</h1><p>{project?.description||'Add context so your team knows what this project is about.'}</p></div><select disabled={selected?.role==="member"} aria-label="Project status" className="select-control" value={project?.status} onChange={async e=>{await api.patch(`/projects/${projectId}`,{status:e.target.value});qc.invalidateQueries({queryKey:['project',projectId]});}}>{PROJECT_STATUS.map(s=><option key={s}>{s}</option>)}</select></div><div className="tabs">{['Board','List','Notes','Discussion','AI'].map(t=><button key={t} className={tab===t?'selected':''} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Board'?<><div className="kanban-mobile-tabs">{STATUS.map(status=><button key={status} className={status===mobileStatus?'selected':''} onClick={()=>setMobileStatus(status)}>{status}<span>{tasks.filter(t=>t.status===status).length}</span></button>)}</div>{tasksLoading?<PageLoading kind="board"/>:tasksError?<ErrorState error={tasksError} retry={refetchTasks}/>:<DndContext onDragEnd={({active,over})=>over&&moveTask(active.id,over.id)}><div className="kanban">{STATUS.map(status=><KanbanColumn key={status} status={status} active={status===mobileStatus} tasks={tasks.filter(t=>t.status===status)} onCreate={createTask} newTitle={newTitle} setNewTitle={setNewTitle} onOpen={setEditingTask}/>)}</div></DndContext>}</>:tab==='List'?tasksError?<ErrorState error={tasksError} retry={refetchTasks}/>:tasks.length?<div className="panel task-list">{tasks.map(t=><TaskLine key={t._id} task={t} move={moveTask} onOpen={setEditingTask}/>)}</div>:<Empty icon={ListTodo} title="No tasks yet" body="Add the first task to start moving work through this project." action={<button className="button primary" onClick={()=>setTab('Board')}><Plus size={15}/> Open board</button>}/>:tab==='Notes'?<Notes projectId={projectId}/>:tab==='Discussion'?<Chat embedded/> :<AIPlanner projectId={projectId} />}{editingTask && <TaskDrawer task={editingTask} workspaceId={selectedId} onClose={()=>setEditingTask(null)} onSaved={()=>{refetchTasks();setEditingTask(null);}} onDeleted={()=>{refetchTasks();setEditingTask(null);}}/>}</>;
}
function KanbanColumn({status,tasks,onCreate,newTitle,setNewTitle,onOpen,active}){const {setNodeRef,isOver}=useDroppable({id:status});return <section ref={setNodeRef} className={`kanban-column ${active?'mobile-active':''} ${isOver?'drag-over':''}`}><div className="column-heading"><span className={`task-mark ${slug(status)}`}/><strong>{status}</strong><span className="column-count">{tasks.length}</span><button className="icon-button mini" title="Add task" aria-label={`Add task to ${status}`} onClick={()=>document.getElementById('new-task-title')?.focus()}><Plus size={15}/></button></div><div className="task-stack">{tasks.map(task=><DraggableTask key={task._id} task={task} onOpen={onOpen}/>)}</div><form className="quick-add" onSubmit={e=>onCreate(e,status)}><input id={status==='To Do'?'new-task-title':undefined} placeholder="+ Add a task" value={newTitle[status]||''} onChange={e=>setNewTitle(current=>({...current,[status]:e.target.value}))}/></form></section>;}
function AvatarStack({users=[]}){const visible=users.slice(0,3),extra=users.length-visible.length;return <span className="avatar-stack" aria-label={users.map(user=>user.name).filter(Boolean).join(', ')}>{visible.map(user=><span className="user-avatar stack-avatar" key={user._id||user.id||user.name} title={user.name}>{user.name?.[0]?.toUpperCase()||'?'}</span>)}{extra>0&&<span className="avatar-overflow">+{extra}</span>}</span>;}
function DraggableTask({task,onOpen}){const {attributes,listeners,setNodeRef,transform,isDragging}=useDraggable({id:task._id});const style={transform:transform?`translate3d(${transform.x}px, ${transform.y}px, 0)`:undefined,opacity:isDragging?0.45:1};return <article ref={setNodeRef} style={style} className="task-card"><div className="task-card-line"><Badge value={task.priority}/><button {...listeners} {...attributes} className="drag-handle" aria-label={`Drag ${task.title}`}><GripVertical size={15}/></button></div><button type="button" className="task-title-button" onClick={()=>onOpen(task)}>{task.title}</button>{task.description&&<p>{task.description}</p>}<div className="task-card-foot"><span>{task.dueDate&&<span className={isPast(new Date(task.dueDate))?'overdue':''}><CalendarDays size={12}/> {format(new Date(task.dueDate),'MMM d')}</span>}</span><AvatarStack users={task.assignees||[]}/></div></article>;}function TaskLine({task,move,onOpen}){return <div className="task-line"><span className={`task-mark ${slug(task.status)}`}/><div className="grow"><button type="button" className="task-line-title" onClick={()=>onOpen?.(task)}>{task.title}</button><small>{task.project?.name||'Task'}{task.dueDate&&<> · Due <span className={isPast(new Date(task.dueDate))&&format(new Date(task.dueDate),'yyyy-MM-dd')!==format(new Date(),'yyyy-MM-dd')?'overdue':undefined}>{format(new Date(task.dueDate),'MMM d')}</span></>}</small></div><Badge value={task.priority}/><select className="select-control small-select" aria-label={`Status for ${task.title}`} value={task.status} onChange={e=>move(task._id,e.target.value)}>{STATUS.map(s=><option key={s}>{s}</option>)}</select></div>;}

function MyTasks(){
  const {selectedId}=useWorkspace();
  const {user}=useAuth();
  const qc=useQueryClient();
  const [editingTask,setEditingTask]=useState(null);
  const [createOpen,setCreateOpen]=useState(false);
  useEffect(()=>{if(new URLSearchParams(location.search).get('create')==='1')setCreateOpen(true);},[location.search]);
  const [newTitle,setNewTitle]=useState('');
  const [projectId,setProjectId]=useState('');
  const [busy,setBusy]=useState(false);
  const {data,isLoading,error,refetch}=useQuery({queryKey:['my-tasks',selectedId],queryFn:()=>api.get('/tasks',{params:{workspaceId:selectedId,assignee:'self',limit:100}}),enabled:!!selectedId});
  const projectsQuery=useQuery({queryKey:['task-create-projects',selectedId],queryFn:()=>api.get('/projects',{params:{workspaceId:selectedId,limit:100}}),enabled:!!selectedId});
  const projects=projectsQuery.data?.items||[];
  useEffect(()=>{if(!projectId&&projects.length)setProjectId(projects[0]._id);},[projectId,projects]);
  const tasks=data?.items||[];
  const buckets={Overdue:[],Today:[], 'This week':[],Later:[]};
  const now=new Date();
  tasks.forEach(task=>{if(task.status==='Completed')return;const due=task.dueDate?new Date(task.dueDate):null;if(due&&isPast(due)&&format(due,'yyyy-MM-dd')!==format(now,'yyyy-MM-dd'))buckets.Overdue.push(task);else if(due&&format(due,'yyyy-MM-dd')===format(now,'yyyy-MM-dd'))buckets.Today.push(task);else if(due&&due<new Date(Date.now()+7*86400000))buckets['This week'].push(task);else buckets.Later.push(task);});
  async function createTask(event){
    event.preventDefault();
    if(!projectId||!newTitle.trim())return;
    setBusy(true);
    try{
      await api.post('/tasks',{workspaceId:selectedId,projectId,title:newTitle.trim(),assignees:user?.id?[user.id]:[]});
      setNewTitle('');setCreateOpen(false);
      await Promise.all([qc.invalidateQueries({queryKey:['my-tasks',selectedId]}),qc.invalidateQueries({queryKey:['project-tasks']})]);
      toast.success('Task created');
    }catch(createError){toast.error(createError.message);}
    finally{setBusy(false);}
  }
  return <>
    <PageHeader eyebrow="PERSONAL" title="My tasks" description="Your assigned work across this workspace." action={<button className="button primary" onClick={()=>setCreateOpen(true)}><Plus size={16}/> New task</button>}/>
    {isLoading?<PageLoading kind="tasks"/>:error?<ErrorState error={error} retry={refetch}/>:Object.values(buckets).every(items=>!items.length)?<Empty icon={ListTodo} title="All caught up" body="Your open tasks will show here when they’re assigned to you." action={<Link className="button secondary" to="/projects">Browse projects</Link>}/>:Object.entries(buckets).filter(([,items])=>items.length>0).map(([title,items])=><section className="task-group" key={title}><h2><span>{title}</span><span className="badge">{items.length}</span></h2>{items.map(task=><TaskLine key={task._id} task={task} move={async(id,status)=>{await api.patch(`/tasks/${id}`,{status});refetch();}} onOpen={setEditingTask}/>)}</section>)}
    {createOpen&&<Modal title="Create a task" close={()=>setCreateOpen(false)}><form onSubmit={createTask}>
      {projects.length?<label>Project<select className="select-control" required value={projectId} onChange={event=>setProjectId(event.target.value)}>{projects.map(project=><option key={project._id} value={project._id}>{project.name}</option>)}</select></label>:projectsQuery.isLoading?<p className="muted">Loading projects?</p>:<p className="muted">Create a project before adding tasks. <Link to="/projects">Go to projects</Link></p>}
      <label>Task title<input autoFocus required minLength={2} maxLength={200} value={newTitle} onChange={event=>setNewTitle(event.target.value)} placeholder="What needs to be done?"/></label>
      <div className="modal-actions"><button type="button" className="button ghost" onClick={()=>setCreateOpen(false)}>Cancel</button><button className="button primary" disabled={busy||!projects.length}>{busy?'Creating?':'Create task'}</button></div>
    </form></Modal>}
    {editingTask&&<TaskDrawer task={editingTask} workspaceId={selectedId} onClose={()=>setEditingTask(null)} onSaved={()=>{refetch();setEditingTask(null);}} onDeleted={()=>{refetch();setEditingTask(null);}}/>}
  </>;
}

function Notes({projectId}) {
  const {selectedId, selected: workspace} = useWorkspace();
  const qc = useQueryClient();
  const [selected, setSelected] = useState('');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const {data, isLoading, error, refetch} = useQuery({queryKey:['notes', selectedId, projectId], queryFn:()=>api.get('/notes',{params:{workspaceId:selectedId,projectId,limit:100}}), enabled:!!selectedId});
  const noteQuery = useQuery({queryKey:['note', selected], queryFn:()=>api.get(`/notes/${selected}`), enabled:!!selected});
  useEffect(()=>{
    if(noteQuery.data?.note){setTitle(noteQuery.data.note.title);setContent(noteQuery.data.note.content || '');}
  },[noteQuery.data]);
  const notes = data?.items || [];
  const canDelete = ['owner','admin'].includes(workspace?.role);
  async function create(){
    try{
      const result=await api.post('/notes',{workspaceId:selectedId,projectId,title:'Untitled note'});
      await qc.invalidateQueries({queryKey:['notes',selectedId,projectId]});
      setSelected(result.note._id);
      toast.success('Note created');
    }catch(e){toast.error(e.message);}
  }
  async function save(){
    try{
      await api.patch(`/notes/${selected}`,{title,content});
      await qc.invalidateQueries({queryKey:['notes',selectedId,projectId]});
      toast.success('Saved');
    }catch(e){toast.error(e.message);}
  }
  async function remove(){
    if(!selected || !confirm('Delete this note? This cannot be undone.'))return;
    try{
      await api.delete(`/notes/${selected}`);
      setSelected('');setTitle('');setContent('');
      await Promise.all([qc.invalidateQueries({queryKey:['notes',selectedId,projectId]}),qc.removeQueries({queryKey:['note',selected]})]);
      toast.success('Note deleted');
    }catch(e){toast.error(e.message);}
  }
  return <div className={`notes-layout ${selected?'has-selection':''}`}>
    <aside className="notes-list">
      <div className="notes-list-head"><strong>Notes</strong><button className="icon-button" onClick={create} title="Create note" aria-label="Create note"><Plus size={17}/></button></div>
      {isLoading?<div className="skeleton notes-list-skeleton"/>:error?<ErrorState error={error} retry={refetch}/>:notes.length?notes.map(note=><button key={note._id} className={`note-item ${selected===note._id?'active':''}`} onClick={()=>setSelected(note._id)}>{note.title}<small>{format(new Date(note.updatedAt),'MMM d')}</small></button>):null}
      {!notes.length&&!isLoading&&!error&&<Empty icon={StickyNote} title="No notes yet" body="Create a note to save a decision or idea for your workspace." action={<button className="button primary" onClick={create}><Plus size={14}/> New note</button>}/>}
    </aside>
    {selected?<section className="note-editor">
      {noteQuery.isLoading?<span className="muted">Loading note?</span>:noteQuery.error?<div className="error-state"><p>{noteQuery.error.message}</p><button className="button secondary" onClick={noteQuery.refetch}>Try again</button></div>:<>
        <div className="note-editor-head"><button className="button ghost notes-back" onClick={()=>setSelected('')}>← Notes</button><input className="note-title" value={title} onChange={e=>setTitle(e.target.value)} aria-label="Note title"/>{canDelete&&<button className="button danger" onClick={remove}><Trash2 size={14}/> Delete</button>}</div>
        <textarea value={content} onChange={e=>setContent(e.target.value)} aria-label="Note content" placeholder="Capture a thought, decision, or plan?"/>
        <div className="editor-foot"><span className="muted">Saved notes are visible to workspace members.</span><button className="button primary" onClick={save}>Save note</button></div>
      </>}
    </section>:<div className="note-placeholder"><StickyNote size={24}/><p>Select a note or create one to get started.</p></div>}
  </div>;
}
function Chat({embedded=false}) {
  const {selectedId}=useWorkspace();
  const [messages,setMessages]=useState([]),[text,setText]=useState(''),[connection,setConnection]=useState('connecting');
  const socketRef=useMemo(()=>({current:null}),[]),listRef=useRef(null),stickToBottom=useRef(true);
  useEffect(()=>{let socket;let alive=true;import('socket.io-client').then(({io})=>{if(!alive)return;socket=io(import.meta.env.VITE_SOCKET_URL||'http://localhost:5000',{withCredentials:true,autoConnect:true});socketRef.current=socket;socket.on('connect',()=>{setConnection('connected');socket.emit('workspace:join',selectedId,result=>{if(!result?.success)setConnection('denied');});});socket.on('disconnect',()=>setConnection('reconnecting'));socket.on('connect_error',()=>setConnection('offline'));socket.on('message:new',m=>setMessages(prev=>prev.some(x=>x.id===m.id)?prev:[...prev,m]));});return()=>{alive=false;socket?.disconnect();};},[selectedId]);
  const {data}=useQuery({queryKey:['messages',selectedId],queryFn:()=>api.get('/messages',{params:{workspaceId:selectedId,limit:50}}),enabled:!!selectedId});
  useEffect(()=>{if(data?.items)setMessages(data.items.map(m=>({id:m._id,content:m.content,createdAt:m.createdAt,sender:m.sender})));},[data]);
  useEffect(()=>{const list=listRef.current;if(list&&stickToBottom.current)list.scrollTop=list.scrollHeight;},[messages]);
  function send(e){e.preventDefault();const value=text.trim();if(!value)return;if(connection!=='connected'){toast.error('Chat is offline. Try again when reconnected.');return;}socketRef.current.emit('message:send',{workspaceId:selectedId,content:value},result=>{if(!result?.success)toast.error(result?.error||'Message failed');});setText('');}
  let previous=null;
  return <section className={`chat-panel ${embedded?'embedded':''}`}><div className="chat-head"><div><strong>Workspace chat</strong><small>Messages are visible to workspace members</small></div><span className={`connection ${connection}`} title={connection} aria-label={`Chat ${connection}`}><i/></span></div><div className="message-list" ref={listRef} onScroll={e=>{const el=e.currentTarget;stickToBottom.current=el.scrollHeight-el.scrollTop-el.clientHeight<100;}}>{messages.map(m=>{const time=new Date(m.createdAt),dayKey=format(time,'yyyy-MM-dd'),prev=previous;const sameDay=prev&&format(new Date(prev.createdAt),'yyyy-MM-dd')===dayKey;const grouped=sameDay&&String(prev.sender?._id||prev.sender?.id)===String(m.sender?._id||m.sender?.id)&&time-new Date(prev.createdAt)<=5*60*1000;previous=m;return <Fragment key={m.id}>{(!prev||!sameDay)&&<div className="chat-day-separator"><span>{format(time,'MMMM d, yyyy')}</span></div>}<article className={`message ${grouped?'message-grouped':''}`}>{!grouped&&<span className="user-avatar small-avatar">{m.sender?.name?.[0]||'?'}</span>}<div><div className="message-meta">{!grouped&&<b>{m.sender?.name||'Teammate'}</b>}<time>{format(time,'h:mm a')}</time></div><p>{m.content}</p></div></article></Fragment>;})}{!messages.length&&<Empty icon={MessageSquare} title="Start the conversation" body="Share an update or ask your team a question."/>}</div><form className="chat-composer" onSubmit={send}><input value={text} onChange={e=>setText(e.target.value)} maxLength={4000} placeholder="Message your workspace…" aria-label="Message"/><button className="button primary" disabled={!text.trim()}>Send</button></form></section>;
}function Members(){
 const {selectedId,selected}=useWorkspace(),qc=useQueryClient();const {data,isLoading,error,refetch}=useQuery({queryKey:['members',selectedId],queryFn:()=>api.get(`/workspaces/${selectedId}/members`),enabled:!!selectedId});const [inviteOpen,setInviteOpen]=useState(false),[inviteRole,setInviteRole]=useState('member'),[inviteUrl,setInviteUrl]=useState(''),[busy,setBusy]=useState(false);
 async function invite(e){e.preventDefault();setBusy(true);try{const data=await api.post(`/workspaces/${selectedId}/invitations`,{role:inviteRole,expiresInDays:7,maxUses:1});setInviteUrl(data.invitation.inviteUrl);toast.success('Invitation link created');}catch(err){toast.error(err.message);}finally{setBusy(false);}}
 async function changeRole(userId,role){try{await api.patch(`/workspaces/${selectedId}/members/${userId}/role`,{role});await qc.invalidateQueries({queryKey:['members',selectedId]});toast.success('Member role updated');}catch(err){toast.error(err.message);}}
 async function remove(userId,name){if(!confirm(`Remove ${name} from this workspace?`))return;try{await api.delete(`/workspaces/${selectedId}/members/${userId}`);await qc.invalidateQueries({queryKey:['members',selectedId]});toast.success('Member removed');}catch(err){toast.error(err.message);}}
 return <><PageHeader eyebrow="WORKSPACE" title="Members" description="People with access to this workspace." action={['owner','admin'].includes(selected?.role)&&<button className="button primary" onClick={()=>{setInviteOpen(true);setInviteUrl('');}}><Plus size={16}/> Invite member</button>}/>{isLoading?<PageLoading kind="members"/>:error?<ErrorState error={error} retry={refetch}/>:<div className="panel member-list">{(data?.items||[]).map(m=><div className="member-row" key={m._id}><span className="user-avatar">{m.user?.name?.[0]}</span><span className="grow"><b>{m.user?.name}</b><small>{m.user?.email}</small></span>{selected?.role==='owner'&&m.role!=='owner'?<select className="select-control small-select" value={m.role} aria-label={`Role for ${m.user?.name}`} onChange={e=>changeRole(m.user._id,e.target.value)}><option value="member">Member</option><option value="admin">Admin</option></select>:<Badge value={m.role}/>}{m.role!=='owner'&&(['owner','admin'].includes(selected?.role))&&<button className="icon-button" title="Remove member" aria-label={`Remove ${m.user?.name}`} onClick={()=>remove(m.user._id,m.user.name)}><X size={16}/></button>}</div>)}{!data?.items?.length&&<Empty icon={Users} title="No members yet" body="Create a workspace to get started."/>}</div>}<p className="muted tiny member-invite-note">Workspace invitations use expiring, single-use links. Share them only with the teammate you intend to add.</p>{inviteOpen&&<Modal title="Invite a teammate" close={()=>setInviteOpen(false)}>{inviteUrl?<div className="invite-result"><p>This link expires in 7 days and can be used once.</p><div className="invite-link"><input readOnly value={inviteUrl}/><button className="button secondary" onClick={async()=>{await navigator.clipboard.writeText(inviteUrl);toast.success('Link copied');}}>Copy link</button></div><div className="modal-actions"><button className="button primary" onClick={()=>setInviteOpen(false)}>Done</button></div></div>:<form onSubmit={invite}><label>Workspace role<select className="select-control" value={inviteRole} onChange={e=>setInviteRole(e.target.value)}><option value="member">Member</option>{selected?.role==='owner'&&<option value="admin">Admin</option>}</select></label><p className="muted tiny">Admins can manage workspace members and resources.</p><div className="modal-actions"><button type="button" className="button ghost" onClick={()=>setInviteOpen(false)}>Cancel</button><button className="button primary" disabled={busy}>{busy?'Creating…':'Create invite link'}</button></div></form>}</Modal>}</>;
}


function JoinWorkspace(){const {search}=useLocation();const navigate=useNavigate();const {refresh}=useWorkspace();const token=new URLSearchParams(search).get('token');const [state,setState]=useState({loading:true,error:''});const started=useRef(false);useEffect(()=>{if(started.current)return;started.current=true;let alive=true;if(!token){setState({loading:false,error:'This invitation link is missing its token.'});return;}api.post('/workspaces/invitations/accept',{token}).then(async data=>{if(!alive)return;await refresh();setState({loading:false,error:''});toast.success(`You joined ${data.workspace?.name||'the workspace'}`);navigate('/members',{replace:true});}).catch(error=>alive&&setState({loading:false,error:error.message}));return()=>{alive=false;};},[token]);return <div className="join-page">{state.loading?<><div className="spinner"/><p>Checking your invitation…</p></>:state.error?<><span className="empty-icon"><Users size={22}/></span><h2>Invitation unavailable</h2><p>{state.error}</p><Link className="button secondary" to="/">Go to your workspace</Link></>:<p>Joining workspace…</p>}</div>;}
function Profile(){
  const {user,updateProfile,logout}=useAuth();
  const {selected}=useWorkspace();
  const navigate=useNavigate(),qc=useQueryClient();
  const [tab,setTab]=useState('Account'),[name,setName]=useState(user?.name||''),[workspaceName,setWorkspaceName]=useState(selected?.name||''),[workspaceDescription,setWorkspaceDescription]=useState(selected?.description||'');
  useEffect(()=>{setWorkspaceName(selected?.name||'');setWorkspaceDescription(selected?.description||'');},[selected?._id,selected?.name,selected?.description]);
  async function saveAccount(e){e.preventDefault();try{await updateProfile({name});toast.success('Profile updated');}catch(err){toast.error(err.message);}}
  async function saveWorkspace(e){e.preventDefault();if(!selected?._id)return;try{await api.patch(`/workspaces/${selected._id}`,{name:workspaceName,description:workspaceDescription});await qc.invalidateQueries({queryKey:['workspaces']});toast.success('Workspace updated');}catch(err){toast.error(err.message);}}
  async function signOut(){try{await logout();qc.clear();navigate('/login',{replace:true});}catch(err){toast.error(err.message);}}
  return <><PageHeader eyebrow="SETTINGS" title="Settings" description="Manage your account and workspace."/><div className="settings-tabs" role="tablist" aria-label="Settings sections"><button role="tab" aria-selected={tab==='Account'} className={tab==='Account'?'selected':''} onClick={()=>setTab('Account')}>Account</button><button role="tab" aria-selected={tab==='Workspace'} className={tab==='Workspace'?'selected':''} onClick={()=>setTab('Workspace')}>Workspace</button></div>{tab==='Account'?<section className="panel profile-panel settings-panel"><h2>Account</h2><form onSubmit={saveAccount}><label>Name<input value={name} maxLength={80} onChange={e=>setName(e.target.value)}/></label><label>Email<input value={user?.email||''} disabled/></label><button className="button primary">Save profile</button></form><div className="profile-signout"><div><strong>Sign out</strong><p className="muted tiny">Sign out of your TeamForge account on this device.</p></div><button className="button danger" type="button" onClick={signOut}><LogOut size={15}/> Sign out</button></div></section>:<section className="panel profile-panel settings-panel"><h2>Workspace</h2>{['owner','admin'].includes(selected?.role)?<form onSubmit={saveWorkspace}><label>Workspace name<input value={workspaceName} maxLength={100} onChange={e=>setWorkspaceName(e.target.value)}/></label><label>Description<textarea rows="4" maxLength={1000} value={workspaceDescription} onChange={e=>setWorkspaceDescription(e.target.value)}/></label><button className="button primary">Save workspace</button>{selected?.role==='owner'&&<div className="workspace-danger-zone"><strong>Danger zone</strong><p className="muted tiny">Deleting this workspace permanently removes its projects, tasks, notes, messages, and members.</p><button type="button" className="button danger" onClick={async()=>{if(!selected?._id||selected.role!=='owner')return;if(!window.confirm('Delete this workspace and all of its data? This cannot be undone.'))return;try{await api.delete(`/workspaces/${selected._id}`);await qc.invalidateQueries({queryKey:['workspaces']});qc.removeQueries({queryKey:['dashboard']});navigate('/',{replace:true});toast.success('Workspace deleted');}catch(err){toast.error(err.message);}}}><Trash2 size={15}/> Delete workspace</button></div>}</form>:<p className="muted">Only workspace owners and admins can change workspace details.</p>}</section>}</>;
}function AppRoutes(){return <Routes><Route path="/login" element={<AuthPage mode="login"/>}/><Route path="/register" element={<AuthPage mode="register"/>}/><Route element={<RequireAuth/>}><Route element={<Shell/>}><Route index element={<Dashboard/>}/><Route path="projects" element={<Projects/>}/><Route path="projects/:projectId" element={<ProjectDetail/>}/><Route path="my-tasks" element={<MyTasks/>}/><Route path="notes" element={<Notes/>}/><Route path="chat" element={<Chat/>}/><Route path="members" element={<Members/>}/><Route path="ai" element={<AIPlanner/>}/><Route path="join" element={<JoinWorkspace/>}/><Route path="settings" element={<Profile/>}/><Route path="profile" element={<Profile/>}/></Route></Route><Route path="*" element={<Navigate to="/" replace/>}/></Routes>;}
export default function App(){return <AppRoutes/>;}





























